import React, {useEffect, useEffectEvent,useState,useContext} from 'react';

import { useParams } from 'react-router-dom/cjs/react-router-dom.min';

import Input from '../../shared/components/FormElements/Input';
import Button from '../../shared/components/FormElements/Button';
import { VALIDATOR_REQUIRE, VALIDATOR_MINLENGTH } from '../../shared/components/util/validators';

import './PlaceForm.css';

import useForm from '../../shared/hooks/form-hook';

import Card from '../../shared/components/UIElements/Card';

import { useHttpClient } from '../../shared/hooks/http-hook';
import ErrorModal from '../../shared/components/UIElements/ErrorModal';
import LoadingSpinner from '../../shared/components/UIElements/LoadingSpinner';

import { useHistory } from 'react-router-dom/cjs/react-router-dom.min';
import { AuthContext } from '../../shared/context/auth-context';


const UpdatePlace = () => {
    const auth=useContext(AuthContext);

    const {isLoading,error,sendRequest,clearError}=useHttpClient();

    const [loadedPlace,setLoadedPlace]=useState();

    const placeId=useParams().placeId;
    const history=useHistory();


    const [formState,inputHandler,setFormData]=useForm({
        title: {
            value: '',
            isValid: false
        },
        description: {
            value: '',
            isValid: false
        }
    },
        false
    );

    useEffect(()=>{
        const fetchPlace=async()=>{
            try{
                const responseData=await sendRequest(`${process.env.REACT_APP_BACKEND_URL_API}/places/${placeId}`);
                setLoadedPlace(responseData.place);
                setFormData(
                    {
                        title: {
                            value: loadedPlace.title,
                            isValid: true
                        },
                        description: {
                            value: loadedPlace.description,
                            isValid: true
                        }
                    },
                    true
            );
            }catch(err){
                //http-hook handles it
            }
        };
        fetchPlace();
    },[sendRequest,placeId]);


    //this is where we save the values we entered 
    const placeUpdateSubmitHandler = async event => {
        event.preventDefault();
        try{
            await sendRequest(
                `${process.env.REACT_APP_BACKEND_URL_API}/places/${placeId}`,
                'PATCH',
                JSON.stringify({
                    title: formState.inputs.title.value,
                    description: formState.inputs.description.value
                }),
                {
                    'Content-Type':'application/json',
                    Authorization: 'Bearer '+auth.token
                }
            );
            history.push('/'+auth.userId+'/places')
        }catch(err){

        }
    }

    if(isLoading){
        return(
            <div className='center'>
                <LoadingSpinner asOverlay/>
            </div>
        );
    }



    //if no loaded place and no error
    if(!loadedPlace&&!error){
        return(
            <div className='center'>
                <Card>
                    <h2>could not find a place!</h2>
                </Card>
            </div>
        );
    }

    return <React.Fragment>
        <ErrorModal error={error} onClear={clearError}/>
        {/*if we are not loading and have a loaded place then show the form */}
        {!isLoading&&loadedPlace&&<form className='place-form' onSubmit={placeUpdateSubmitHandler}>
            <Input
                id="title"
                element="input"
                type="text"
                label="Title"
                validators={[VALIDATOR_REQUIRE()]}
                errorText="Please enter a valid title"
                onInput={inputHandler}
                initialValue={loadedPlace.title}
                initialValid={true}
            />
            <Input
                id="description"
                element="textarea"
                label="Description"
                validators={[VALIDATOR_MINLENGTH(5)]}
                errorText="Please enter a valid title"
                onInput={inputHandler}
                initialValue={loadedPlace.description}
                initialValid={true}
            />
            <Button type="submit" disabled={!formState.isValid} >
                UPDATE PLACE
            </Button>
        </form>}
    </React.Fragment>

};

export default UpdatePlace;